import { useMemo, useState } from 'react';
import {
  Badge,
  Pagination,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from '@jinx-ui/react';

type UserStatus = 'active' | 'disabled';

interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_TONE: Record<UserStatus, 'success' | 'neutral'> = {
  active: 'success',
  disabled: 'neutral',
};

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const currentUsers = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, currentPage]);

  return (
    <div className="jx-stack">
      <Table className="jx-table">
        <TableHead>
          <TableRow>
            <TableHeaderCell>Имя</TableHeaderCell>
            <TableHeaderCell>Роль</TableHeaderCell>
            <TableHeaderCell>Статус</TableHeaderCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {currentUsers.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge tone={STATUS_TONE[user.status]} className="jx-badge">
                  {STATUS_LABEL[user.status]}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <Pagination
        className="jx-pagination"
        page={currentPage}
        pageCount={pageCount}
        onPageChange={setPage}
      />
    </div>
  );
}

